'use strict';

// MODULES //

var tape = require( 'tape' );
var proxyquire = require( 'proxyquire' );
var BigInt = require( '@stdlib/bigint/ctor' );
var add = require( '@stdlib/number/uint64/base/add' );
var isFunction = require( '@stdlib/assert/is-function' );
var hasOwnProp = require( '@stdlib/assert/has-own-property' );
var Float64Array = require( '@stdlib/array/float64' );
var Uint64 = require( '@stdlib/number/uint64/ctor' );
var Uint32Array = require( '@stdlib/array/uint32' );
var Uint64Array = require( './../lib' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof Uint64Array, 'function', 'main export is a function' );
	t.end();
});

tape( 'attached to the main export is a `from` method for creating a 64-bit unsigned integer array from an array-like object or iterable', function test( t ) {
	var arr;

	t.strictEqual( hasOwnProp( Uint64Array, 'from' ), true, 'has property' );
	t.strictEqual( isFunction( Uint64Array.from ), true, 'has method' );

	arr = Uint64Array.from( [] );
	t.strictEqual( arr instanceof Uint64Array, true, 'returns expected value' );

	t.end();
});

tape( 'the method throws an error if invoked with a `this` context which is not a constructor', function test( t ) {
	var values;
	var i;

	values = [
		'5',
		5,
		NaN,
		true,
		false,
		null,
		void 0,
		{},
		[]
	];
	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[i] ), TypeError, 'throws an error when provided '+values[i] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			return Uint64Array.from.call( value, [] );
		};
	}
});

