tape( 'the method returns a 64-bit unsigned integer array', function test( t ) {
	var arr;
	var v;
	var u;

	// Generic array:
	arr = Uint64Array.from( [] );
	t.strictEqual( arr instanceof Uint64Array, true, 'returns expected value' );

	v = arr.length;
	t.strictEqual( v, 0, 'returns expected value' );

	arr = Uint64Array.from( [ 1, 2, 3, 4 ] );
	t.strictEqual( arr instanceof Uint64Array, true, 'returns expected value' );

	v = arr.length;
	t.strictEqual( v, 4, 'returns expected value' );

	// Generic array containing 64-bit unsigned integers:
	arr = Uint64Array.from( [ new Uint64( 1 ) ] );
	t.strictEqual( arr instanceof Uint64Array, true, 'returns expected value' );

	v = arr.length;
	t.strictEqual( v, 1, 'returns expected value' );

	u = new Uint64( 1 );
	arr = Uint64Array.from( [ u, 1.0 ] );
	t.strictEqual( arr instanceof Uint64Array, true, 'returns expected value' );

	v = arr.length;
	t.strictEqual( v, 2, 'returns expected value' );

	// Typed array:
	arr = Uint64Array.from( new Float64Array( 0 ) );
	t.strictEqual( arr instanceof Uint64Array, true, 'returns expected value' );

	v = arr.length;
	t.strictEqual( v, 0, 'returns expected value' );

	arr = Uint64Array.from( new Float64Array( [ 1.0, 1.0 ] ) );
	t.strictEqual( arr instanceof Uint64Array, true, 'returns expected value' );

	v = arr.length;
	t.strictEqual( v, 2, 'returns expected value' );

	// Unsigned integer typed array:
	arr = Uint64Array.from( new Uint32Array( 0 ) );
	t.strictEqual( arr instanceof Uint64Array, true, 'returns expected value' );

	v = arr.length;
	t.strictEqual( v, 0, 'returns expected value' );

	arr = Uint64Array.from( new Uint32Array( [ 1, 1 ] ) );
	t.strictEqual( arr instanceof Uint64Array, true, 'returns expected value' );

	v = arr.length;
	t.strictEqual( v, 2, 'returns expected value' );

	arr = Uint64Array.from( new Uint64Array( 0 ) );
	t.strictEqual( arr instanceof Uint64Array, true, 'returns expected value' );

	v = arr.length;
	t.strictEqual( v, 0, 'returns expected value' );

	arr = Uint64Array.from( new Uint64Array( [ 1, 1 ] ) );
	t.strictEqual( arr instanceof Uint64Array, true, 'returns expected value' );

	v = arr.length;
	t.strictEqual( v, 2, 'returns expected value' );

	t.end();
});

tape( 'the method returns a 64-bit unsigned integer array (iterable)', function test( t ) {
	var Uint64Array;
	var iter1;
	var iter2;
	var iter3;
	var arr;
	var v;

	Uint64Array = proxyquire( './../lib/main.js', {
		'@stdlib/assert/has-iterator-symbol-support': hasSupport,
		'@stdlib/symbol/iterator': '__SYMBOL_ITERATOR__'
	});

	iter1 = {
		'next': next1,
		'i': 0,
		'N': 4
	};

	arr = Uint64Array.from( createIterable( iter1 ) );
	t.strictEqual( arr instanceof Uint64Array, true, 'returns expected value' );

	v = arr.length;
	t.strictEqual( v, iter1.N, 'returns expected value' );

	iter2 = {
		'next': next2,
		'i': 0,
		'N': 4
	};

	arr = Uint64Array.from( createIterable( iter2 ) );
	t.strictEqual( arr instanceof Uint64Array, true, 'returns expected value' );

	v = arr.length;
	t.strictEqual( v, iter2.N, 'returns expected value' );

	iter2 = {
		'next': next2,
		'i': 0,
		'N': 4
	};

	arr = Uint64Array.from( createIterable( iter2 ) );
	t.strictEqual( arr instanceof Uint64Array, true, 'returns expected value' );

	v = arr.length;
	t.strictEqual( v, iter2.N, 'returns expected value' );

	iter3 = {
		'next': next3,
		'i': 0,
		'N': 4
	};

	arr = Uint64Array.from( createIterable( iter3 ) );
	t.strictEqual( arr instanceof Uint64Array, true, 'returns expected value' );

	v = arr.length;
	t.strictEqual( v, iter3.N, 'returns expected value' );

	t.end();

	function hasSupport() {
		return true;
	}

	function createIterable( iterator ) {
		var it = {};
		it[ '__SYMBOL_ITERATOR__' ] = iterable;
		return it;

		function iterable() {
			return iterator;
		}
	}

	function next1() {
		iter1.i += 1;
		if ( iter1.i <= iter1.N ) {
			return {
				'value': new Uint64( 1 )
			};
		}
		return {
			'done': true
		};
	}

	function next2() {
		iter2.i += 1;
		if ( iter2.i <= iter2.N ) {
			return {
				'value': 1
			};
		}
		return {
			'done': true
		};
	}

	function next3() {
		iter3.i += 1;
		if ( iter3.i <= iter3.N ) {
			return {
				'value': BigInt( 1 )
			};
		}
		return {
			'done': true
		};
	}
});

tape( 'the method supports providing a "map" function which is invoked for each source element', function test( t ) {
	var arr;
	var v;

	// Generic array:
	arr = Uint64Array.from( [], clbk1 );
	t.strictEqual( arr instanceof Uint64Array, true, 'returns expected value' );

	v = arr.length;
	t.strictEqual( v, 0, 'returns expected value' );

	arr = Uint64Array.from( [ 1, 2, 3, 4 ], clbk1 );
	t.strictEqual( arr instanceof Uint64Array, true, 'returns expected value' );

	v = arr.length;
	t.strictEqual( v, 4, 'returns expected value' );

	// Generic array containing 64-bit unsigned integers:
	arr = Uint64Array.from( [ new Uint64( 1 ) ], clbk2 );
	t.strictEqual( arr instanceof Uint64Array, true, 'returns expected value' );

	v = arr.length;
	t.strictEqual( v, 1, 'returns expected value' );

	arr = Uint64Array.from( [ new Uint64( 1 ) ], clbk3 );
	t.strictEqual( arr instanceof Uint64Array, true, 'returns expected value' );

	v = arr.length;
	t.strictEqual( v, 1, 'returns expected value' );

	// Typed array:
	arr = Uint64Array.from( new Float64Array( 0 ), clbk1 );
	t.strictEqual( arr instanceof Uint64Array, true, 'returns expected value' );

	v = arr.length;
	t.strictEqual( v, 0, 'returns expected value' );

	arr = Uint64Array.from( new Float64Array( [ 1.0, 1.0 ] ), clbk1 );
	t.strictEqual( arr instanceof Uint64Array, true, 'returns expected value' );

	v = arr.length;
	t.strictEqual( v, 2, 'returns expected value' );

	// Unsigned typed array:
	arr = Uint64Array.from( new Uint64Array( 0 ), clbk3 );
	t.strictEqual( arr instanceof Uint64Array, true, 'returns expected value' );

	v = arr.length;
	t.strictEqual( v, 0, 'returns expected value' );

	arr = Uint64Array.from( new Uint64Array( [ 1, 1 ] ), clbk3 );
	t.strictEqual( arr instanceof Uint64Array, true, 'returns expected value' );

	v = arr.length;
	t.strictEqual( v, 2, 'returns expected value' );

	t.end();

	function clbk1( v ) {
		return v;
	}

	function clbk2() {
		return new Uint64( 1 );
	}

	function clbk3( v ) {
		return add( v, v );
	}
});

