tape( 'the method supports providing a `this` context for a provided map function', function test( t ) {
	var arr;
	var ctx;

	ctx = {
		'count': 0
	};
	arr = Uint64Array.from( [ 1, 2, 3, 4 ], clbk1, ctx );
	t.strictEqual( arr instanceof Uint64Array, true, 'returns expected value' );
	t.strictEqual( ctx.count, 4, 'returns expected value' );

	ctx = {
		'count': 0
	};
	arr = [ new Uint64( 1 ), new Uint64( 2 ) ];
	arr = Uint64Array.from( arr, clbk2, ctx );
	t.strictEqual( arr instanceof Uint64Array, true, 'returns expected value' );
	t.strictEqual( ctx.count, 2, 'returns expected value' );

	t.end();

	function clbk1( v ) {
		this.count += 1; // eslint-disable-line no-invalid-this
		return add( v, new Uint64( 1 ) );
	}

	function clbk2( v ) {
		this.count += 1; // eslint-disable-line no-invalid-this
		return add( v, v );
	}
});

